import { GameMode, Question, QuestionCategory, QuestionEra, QuestionType } from '../types';

type ItemOptions = {
  category: QuestionCategory;
  era: QuestionEra;
  topic: string;
  question: string;
  answer: string;
  distractors: string[];
  explanation: string;
  difficulty?: Question['difficulty'];
  mode?: GameMode;
  questionType?: QuestionType;
  subjectKey?: string;
  eligibleForRush?: boolean;
  eligibleForDaily?: boolean;
  freshness?: Question['freshness'];
  tags?: string[];
};

function item(id: string, options: ItemOptions): Question {
  const {
    category,
    era,
    topic,
    question,
    answer,
    distractors,
    explanation,
    difficulty = 'medium',
    mode = 'mix',
    questionType = 'standard',
    subjectKey = id,
    eligibleForRush = true,
    eligibleForDaily = true,
    freshness = 'evergreen',
    tags = [topic, category],
  } = options;

  return {
    id,
    mode,
    question,
    questionType,
    category,
    era,
    topic,
    subjectKey,
    tags,
    options: [answer, ...distractors],
    correctAnswer: 0,
    explanation,
    memeContext: 'Internet culture is remixable by design; this clue points to the commonly recognized format or moment.',
    difficulty,
    eligibleForRush,
    eligibleForDaily,
    freshness,
    sourceLabel: 'Editorial reference: documented internet culture history',
  };
}

const classic = (id: string, topic: string, question: string, answer: string, distractors: string[], explanation: string, difficulty: Question['difficulty'] = 'easy', extra: Partial<ItemOptions> = {}) => item(id, {
  category: 'classic_memes',
  era: extra.era ?? 'classic',
  topic,
  question,
  answer,
  distractors,
  explanation,
  difficulty,
  ...extra,
});

